prog='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    for r in range(h):
        if r < 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1
            continue
        if r == 2:
            for c in range(w):
                if out[r][c] == 0:
                    out[r][c] = 1 if c < 2 else 4
            continue
        for c in range(min(3, w)):
            if out[r][c] == 0:
                out[r][c] = 4 if c == 2 else 1
        # The colored rows repeat a short cycle. Infer its length and values
        # from the intact cells, ignoring occasional irregular cells at the edge.
        observed = [(c, grid[r][c]) for c in range(3, w) if grid[r][c] != 0]
        best = None
        for period in range(2, 10):
            vals = {}
            for c, v in observed:
                vals.setdefault(c % period, []).append(v)
            cycle = {k: max(set(vs), key=vs.count) for k, vs in vals.items()}
            score = sum(v == cycle[c % period] for c, v in observed)
            if best is None or score > best[0]:
                best = (score, period, cycle)
        cycle = best[2]
        fallback = next(iter(cycle.values()))
        for c in range(3, w):
            if out[r][c] == 0:
                out[r][c] = cycle.get(c % best[1], fallback)
    return out
'''
